        GridLayout animalListDisplayLayout = new GridLayout(0,5);
        animalListDisplayLayout.setHgap(10);
        animalListDisplayLayout.setVgap(7);

        JPanel animalListDisplay = new JPanel(animalListDisplayLayout);

