218	    /**
219	     * Retrieves all inputs in the correct form using helper methods
220	     * defined in this class and launches the simulation.
221	     *
222	     * @param habitatChoiceDisplay (JComboBox<String>) The ComboBox used by the user to select a habitat.
223	     * @param animalNumberReceivers (ArrayList<JTextField>) The list of TextFields used by the user to input numbers of each animal to create.
224	     * @param climateChangeScenarioChoiceDisplay (JComboBox<String>) The ComboBox used by the user to select a climate change scenario.
225	     */
226	    private void getInputsAndLaunchSimulation(
227	        JComboBox<String> habitatChoiceDisplay,
228	        ArrayList<JTextField> animalNumberReceivers,
229	        JComboBox<String> climateChangeScenarioChoiceDisplay
230	    )
231	    {
232	        String chosenHabitat = getHabitatInput(habitatChoiceDisplay);
233	        if (chosenHabitat != null)
234	        {
235	            ArrayList<Integer> numbersInputted = getNumericValuesOfUserInputs(animalNumberReceivers);
236	            if (numbersInputted != null) {
237	                Map<String, Integer> selectedAnimals = generateAnimalDictionary(numbersInputted);
238	                if (selectedAnimals != null) {
239	                    String chosenSimulation = getScenarioInput(climateChangeScenarioChoiceDisplay);
240	                    launchSimulation(chosenHabitat, selectedAnimals, chosenSimulation);
241	                }
242	            }
243	        }
244	    }
