246	    /**
247	     * Return a list of Integers from the Strings inputted by the user in the various TextFields.
248	     * Source for try/catch construct to catch non-numerical values: https://stackabuse.com/java-check-if-string-is-a-number/
249	     *
250	     * @param inputsList (ArrayList<JTextField>) The list of TextFields object in which the user inputted data.
251	     * @return (ArrayList<Integer>) The list of integers inputted by the user.
252	     */
253	    private ArrayList<Integer> getNumericValuesOfUserInputs (ArrayList<JTextField> inputsList)
254	    {
255	        ArrayList<Integer> inputtedNumbers = new ArrayList<>();
256	        for (JTextField inputReceiver : inputsList)
257	        {
258	            String inputValue = inputReceiver.getText();
259	            try {
260	                int numericValue = Integer.parseInt(inputValue);
261	                inputtedNumbers.add(numericValue);
262	            } catch (NumberFormatException e) {
263	                throwErrorMessage("One of the values inputted is not a number or one cell was left blank, please try again.");
264	                return null;
265	            }
266	        }
267	        return inputtedNumbers;
268	    }
