279	    /**
280	     * Generates a HashMap associating the name of each animal with the number
281	     * of this animal that must be created. This method heavily relies on the fact
282	     * that animal names are stored in the animalList in the same order that they were on screen.
283	     *
284	     * @param numberOfEachAnimals (ArrayList<Integer>) The list of animal counts aligned with the displayed animal list.
285	     */
286	    private Map<String, Integer> generateAnimalDictionary(ArrayList<Integer> numberOfEachAnimals)
287	    {
288	        if (numberOfEachAnimals.size() != animalList.size()) {
289	            return null;
290	        }
291	
292	        HashMap<String, Integer> selectedAnimals = new HashMap<>();
293	        for (int i=0; i<numberOfEachAnimals.size(); i++) {
294	            selectedAnimals.put(animalList.get(i), numberOfEachAnimals.get(i));
295	        }
296	        return selectedAnimals;
297	    }
